const HITS = new Map();
function limited(key, max, windowMs) { const t = now(); const a = (HITS.get(key) || []).filter(x => t - x < windowMs); a.push(t); HITS.set(key, a); return a.length > max; }
setInterval(() => { const t = now(); for (const [k, a] of HITS) if (!a.some(x => t - x < 3600e3)) HITS.delete(k); }, 600e3).unref();

/* ---------- http helpers ---------- */
function send(res, code, obj, headers = {}) { const b = JSON.stringify(obj); res.writeHead(code, Object.assign({ 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' }, headers)); res.end(b); }
function body(req, limit) {
  return new Promise((ok, bad) => { let n = 0; const ch = []; req.on('data', d => { n += d.length; if (n > limit) { bad(Object.assign(new Error('too large'), { code: 413 })); req.destroy(); } else ch.push(d); }); req.on('end', () => { try { ok(ch.length ? JSON.parse(Buffer.concat(ch).toString('utf8')) : {}); } catch (e) { bad(Object.assign(new Error('bad json'), { code: 400 })); } }); req.on('error', bad); });
}
const ip = req => (String(req.headers['x-forwarded-for'] || '').split(',')[0].trim()) || req.socket.remoteAddress;
function sameOrigin(req) { const o = req.headers.origin; if (!o) return true; try { return new URL(o).host === req.headers.host; } catch (e) { return false; } }

/* ---------- writes with hooks ---------- */
async function save(c, id, doc) { doc.id = id; doc._seq = ++SEQ; await S.put(c, id, doc); }
async function remove(c, id) { await S.del(c, id); TOMB.push({ c, id, seq: ++SEQ }); if (TOMB.length > 5000) TOMB_FLOOR = TOMB.splice(0, 1000).pop().seq; }
const vkey = u => crypto.createHash('sha1').update(JSON.stringify([u ? [u.id, u.role, u.status] : null, (S.get('settings', 'main') || {}).perms || null, logic.resFee(S)])).digest('hex').slice(0, 12);
async function audit(u, action) { await save('audit', uid('a'), { at: now(), user: u ? u.name + ' (' + u.role + ')' : 'system', action: String(action).slice(0, 200) }); }
async function notifyUser(userId, title, body, o = {}) {
  const u = S.get('users', userId); if (!u) return;
  await save('notifs', uid('n'), { userId, title: String(title).slice(0, 200), body: String(body).slice(0, 800), at: now(), read: false });
  if (u.email) sendEmail({ to: u.email, subject: title, text: body });
  if (o.sms && u.phone) sendSMS({ to: u.phone, text: 'ADI: ' + title + ' - ' + body });
}
const usersWith = perm => Object.values(S.all('users')).filter(u => u.status === 'active' && (u.role === 'super_admin' || (perm !== '__super' && (logic.perms(S)[u.role] || []).includes(perm))));
async function nextReceipt(ay) { const n = Number(S.meta.rcpt || Object.values(S.all('payments')).filter(p => p.receiptNo).length) + 1; await S.setMeta('rcpt', n); return 'ADI/RCPT/' + String(ay || logic.AY()).replace('/', '-') + '/' + String(n).padStart(5, '0'); }

async function confirmPayment(p, by, extra = {}) {
  const n = Object.assign({}, p, extra, { status: 'confirmed', receiptNo: p.receiptNo || await nextReceipt(p.ay), confirmedAt: now(), confirmedBy: by });
  await save('payments', p.id, n);
  if (n.kind === 'registration') { const st = S.get('students', n.matric); if (st && st.status !== 'registered') await save('students', st.matric, Object.assign({}, st, { status: 'registered' })); }
  if (/^res_/.test(n.kind)) { for (const r of Object.values(S.all('results')).filter(r => r.matric === n.matric && logic.resKind(r.ay, r.sem) === n.kind)) await save('results', r.id, Object.assign({}, r)); }
  await notifyUser(n.userId, bi('Payment confirmed', 'Paiement confirmé'), n.label + ' — ' + xaf(n.amount) + '. Receipt / Reçu : ' + n.receiptNo, { sms: true });
  return n;
}

// Applies a client write after rules pass: sanitises, enforces amounts, fires side effects.
async function applyWrite(u, c, id, o, n) {
  if (c === 'settings' && n && u && u.role !== 'super_admin') n = Object.assign({}, JSON.parse(JSON.stringify(o || {})), { cls: n.cls });
  if (c === 'liblinks' && n) { const cl = logic.core.libLinkSanitize(n); if (!cl) throw ['invalid link: check the name, the https address and at least one category']; n = Object.assign({}, JSON.parse(JSON.stringify(cl)), { id }); }
  if (c === 'settings' && n && n.assoc !== undefined) n.assoc = JSON.parse(JSON.stringify(logic.core.assocCfg(n.assoc)));
  if (c === 'settings' && n && n.und !== undefined) {                                    // the undertaking forms: cleaned here; the server numbers each new version and dates it
    const cleaned = JSON.parse(JSON.stringify(logic.core.undCfg(n.und))), prev = (o && o.und) ? JSON.parse(JSON.stringify(logic.core.undCfg(o.und))) : {}, strip = x => JSON.stringify(Object.assign({}, x, { v: 0, updated: 0 }));
    Object.keys(cleaned).forEach(k => { const p0 = prev[k]; if (p0 && strip(p0) === strip(cleaned[k])) { cleaned[k].v = p0.v; cleaned[k].updated = p0.updated; } else { cleaned[k].v = (p0 ? p0.v : 1) + 1; cleaned[k].updated = now(); } }); n.und = cleaned;
  }
  if (c === 'settings' && n && n.chat !== undefined) n.chat = JSON.parse(JSON.stringify(logic.core.chatCfg(n.chat)));
  if (c === 'settings' && n && n.cal !== undefined) { const cc = JSON.parse(JSON.stringify(logic.core.calCfg(n.cal))), oc = o && o.cal ? JSON.parse(JSON.stringify(logic.core.calCfg(o.cal))) : null; cc.updated = oc && JSON.stringify(Object.assign({}, oc, { updated: 0 })) === JSON.stringify(Object.assign({}, cc, { updated: 0 })) ? oc.updated : now(); n.cal = cc; }   // the calendar edits are validated here, and "last updated" is stamped by the server
  if (c === 'settings' && n && n.pg !== undefined) n.pg = JSON.parse(JSON.stringify(logic.core.pgCfg(n.pg)));
  if (c === 'settings' && n && n.vis !== undefined) n.vis = JSON.parse(JSON.stringify(logic.core.visCfg(n.vis)));
  if (c === 'settings' && n && n.hr !== undefined) n.hr = JSON.parse(JSON.stringify(logic.core.hrCfg(n.hr)));
  if (c === 'settings' && n && n.cls !== undefined) n.cls = JSON.parse(JSON.stringify(logic.core.clsCfg(n.cls)));
  if (c === 'settings' && n && n.lib !== undefined) n.lib = JSON.parse(JSON.stringify(logic.core.libCfgSanitize(n.lib)));
  if (c === 'settings' && n && n.site !== undefined) n.site = JSON.parse(JSON.stringify(logic.core.siteSanitize(n.site)));   // site appearance: re-validated on the server whatever the browser sent
  if (c === 'users') { n = Object.assign({}, o, n, { pw: o.pw, email: o.email }); if (n.photo && n.photo.length > 200000) throw ['photo too large']; }
  if (c === 'payments') {
    if (!o) {
      const st = R.myStudent(u); if (!st || st.matric !== n.matric) throw ['student'];
      const price = logic.priceFor(S, st, n.kind); if (!price) throw ['unknown fee item'];
      if (price.custom) { if (!(n.amount > 0 && n.amount <= 5e6)) throw ['amount']; } else if (Number(n.amount) !== Number(price.amount)) throw ['amount must be ' + price.amount];
      const ref = String(n.ref || '').trim(); if (ref.length < 6) throw ['transaction id'];
      if (Object.values(S.all('payments')).some(p => String(p.ref).toLowerCase() === ref.toLowerCase())) throw ['duplicate transaction id'];
      n = { userId: u.id, matric: st.matric, payerName: st.name, kind: n.kind, label: String(n.label || price.label).slice(0, 200), amount: Number(n.amount), ref, payerPhone: String(n.payerPhone || '').slice(0, 30), status: 'pending', at: now(), ay: logic.AY(), momoTo: n.momoTo, method: 'manual' };
      await save(c, id, n);
      for (const s of usersWith('verify_payments')) await notifyUser(s.id, bi('Payment to verify', 'Paiement à vérifier'), n.payerName + ' — ' + xaf(n.amount) + ' (' + n.ref + ')');
      return;
    }
    if (n.status === 'confirmed') { await confirmPayment(o, u.name); await audit(u, 'payment confirmed ' + o.ref); return; }
    n = Object.assign({}, o, { status: 'rejected', note: String(n.note || '').slice(0, 300), confirmedBy: u.name, rejectedAt: now() }); await save(c, id, n);
    await notifyUser(o.userId, bi('Payment rejected', 'Paiement rejeté'), o.label + ' — ' + (n.note || ''), { sms: true }); return;
  }
  if (c === 'results') { const r = logic.calcRes(n.ca, n.exam); if (!(n.ca >= 0 && n.ca <= 30 && n.exam >= 0 && n.exam <= 70)) throw ['marks out of range']; n = Object.assign({}, n, r); }
  if ((c === 'events' || c === 'testi') && n !== null) { // clean and validate everything staff submit for the public website
    const str = (v, k) => String(v == null ? '' : v).replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, '').trim().slice(0, k), dateOk = v => /^\d{4}-\d{2}-\d{2}$/.test(v) && !isNaN(new Date(v + 'T12:00:00'));
    if (c === 'events') {
      const cats = ['orientation', 'matriculation', 'graduation', 'opendoor', 'seminar', 'defense', 'sport', 'exhibition'];
      if (!cats.includes(n.cat)) throw ['event type']; if (!str(n.title, 140)) throw ['title']; if (!dateOk(str(n.date, 10))) throw ['date'];
      const end = n.endDate ? str(n.endDate, 10) : ''; if (end && (!dateOk(end) || end < n.date)) throw ['end date'];
      const tm = v => (/^([01]\d|2[0-3]):[0-5]\d$/.test(str(v, 5)) ? str(v, 5) : '');
      n = { cat: n.cat, title: str(n.title, 140), titleFr: str(n.titleFr, 140), date: n.date, endDate: end, time: tm(n.time), endTime: tm(n.endTime), venue: str(n.venue, 120), campus: ['yaounde', 'buea'].includes(n.campus) ? n.campus : 'both',
        desc: String(n.desc || '').replace(/\r/g, '').trim().slice(0, 2000), descFr: String(n.descFr || '').replace(/\r/g, '').trim().slice(0, 2000), status: n.status === 'draft' ? 'draft' : 'published', createdAt: (o && o.createdAt) || now(), updatedAt: now() };
    } else {
      const groups = ['c2023', 'bts24', 'acc24', 'eng24', 'pm25', 'other'];
      if (!str(n.name, 120) || !str(n.text, 1500)) throw ['name and text'];
      n = { name: str(n.name, 120), grp: groups.includes(n.grp) ? n.grp : 'other', label: str(n.label, 80), text: String(n.text).replace(/\r/g, '').trim().slice(0, 1500), textFr: String(n.textFr || '').replace(/\r/g, '').trim().slice(0, 1500), visible: n.visible !== false, featured: !!n.featured, order: Number.isFinite(Number(n.order)) ? Math.round(Number(n.order)) : -now() };
    }
    await save(c, id, n); await audit(u, c + ' saved ' + id); return;
  }
  if (c === 'formb') {
    if (o && o.userId !== u.id) { // Registrar/admin decision on a Form B: only the decision fields change; the server stamps who and when
      if (!(n.status === 'returned' || (n.status === 'validated' && o.status === 'submitted'))) throw ['status'];
      n = Object.assign({}, o, { status: n.status, remark: n.status === 'returned' ? String(n.remark || '').slice(0, 500) : '', validatedAt: n.status === 'validated' ? now() : o.validatedAt, validatedBy: u.name });
      await save(c, id, n); await audit(u, 'form B ' + n.status + ' ' + id); return;
    }
    const st = R.myStudent(u); if (!st || st.matric !== n.matric) throw ['student'];
    const ck = logic.checkFormB(S, st, n, o); if (ck.error) throw [ck.error];
    if (id !== logic.fbKey(st.matric, logic.AY(), ck.sem)) throw ['form B id'];
    let ref = o && o.ref; if (!ref) { const k = Number(S.meta.fbn || 0) + 1; await S.setMeta('fbn', k); ref = 'FB/' + String(logic.AY()).slice(0, 4) + '/' + String(k).padStart(4, '0'); }
    n = { userId: u.id, matric: st.matric, name: st.name, ay: logic.AY(), sem: ck.sem, year: ck.year, credits: ck.credits, courses: ck.courses, status: 'submitted', submittedAt: now(), ref };
    await save(c, id, n); for (const s of usersWith('manage_students')) await notifyUser(s.id, bi('Form B to validate', 'Formulaire B à valider'), st.name + ' (' + st.matric + ') — ' + logic.AY() + ' S' + ck.sem + ' · ' + ck.credits + ' cr'); return;
  }
  if (c === 'trreq' && !o) {
    const fc = logic.trCfg(S)[n.mode]; if (!fc) throw ['mode']; const copies = Math.min(20, Math.max(1, Number(n.copies) || 1));
    n = Object.assign({}, n, { copies, unit: fc.fee, days: fc.days, fee: fc.fee * copies, status: 'submitted', at: now() });
  }
  if (c === 'trreq' && o && ['processing', 'ready', 'collected'].includes(n.status)) {
    const paid = Object.values(S.all('payments')).some(p => p.kind === 'tr_' + id && p.status === 'confirmed'); if (!paid) throw ['transcript fee not paid'];
  }
  if (c === 'notifs' && !o) {
    const title = String(n.title || '').slice(0, 200), text = String(n.body || '').slice(0, 800);
    if (/^(Payment (confirmed|rejected|to verify)|Paiement (confirmé|rejeté|à vérifier))/.test(title) || n.toPerm === 'manage_tickets') return;
    if (n.toPerm) { const list = usersWith(n.toPerm); for (const x of list) await notifyUser(x.id, title, text); return; }
    if (!S.get('users', n.userId)) throw ['user'];
    await notifyUser(n.userId, title, text, { sms: /admitted|admis|ready for collection|prêt à retirer/i.test(title + ' ' + text) }); return;
  }
  if (c === 'tickets' && !o) {
    n = { userId: u ? u.id : null, name: String(u ? u.name : n.name || '').slice(0, 120), email: String(u ? u.email : n.email || '').slice(0, 160), subject: String(n.subject || '').slice(0, 200), msg: String(n.msg || '').slice(0, 4000), status: 'open', at: now(), to: INBOX() };
    if (!n.subject || !n.msg || !/^\S+@\S+\.\S+$/.test(n.email)) throw ['incomplete'];
    await save(c, id, n);
    sendEmail({ to: INBOX(), subject: '[ADI portal] ' + n.subject, text: 'From: ' + n.name + ' <' + n.email + '>\n\n' + n.msg, replyTo: n.email });
    sendEmail({ to: n.email, subject: bi('We received your message', 'Nous avons reçu votre message'), text: 'Subject / Objet : ' + n.subject + '\n\nThe ADI team will reply soon. / L’équipe ADI vous répondra bientôt.' });
    for (const s of usersWith('manage_tickets')) await save('notifs', uid('n'), { userId: s.id, title: bi('New inquiry', 'Nouvelle demande'), body: n.subject, at: now(), read: false });
    return;
  }
  if (c === 'tickets' && o && n.reply && n.reply !== o.reply) { n = Object.assign({}, o, { reply: String(n.reply).slice(0, 4000), status: 'answered', repliedAt: now(), repliedBy: u.name }); await save(c, id, n); sendEmail({ to: o.email, subject: 'Re: ' + o.subject, text: n.reply, replyTo: INBOX() }); return; }
  if (c === 'audit') n = { at: now(), user: u.name + ' (' + u.role + ')', action: String(n.action || '').slice(0, 200) };
  if (c === 'files' && !o) { const blob = await S.getBlob(id); if (!blob) throw ['upload missing']; n = Object.assign({}, n, { size: blob.length, at: now() }); }
  if (c === 'files' && n === null) await S.delBlob(id).catch(() => {});
  if (c === 'courses' && n && (n.level === 'HND' || n.level === 'BTS')) {
    const stOf = x => ({ C: 1, R: 1, E: 1 }[x.status] ? x.status : (x.compulsory === false ? 'E' : 'C'));
    if (stOf(n) !== 'E') {
      const add = Math.max(1, Number(n.credits) || 1);
      const tot = Object.values(S.all('courses')).filter(x => x.id !== id && x.level === n.level && x.specId === n.specId && Number(x.year) === Number(n.year || 1) && Number(x.sem) === Number(n.sem || 1) && stOf(x) !== 'E').reduce((a, x) => a + (Number(x.credits) || 0), 0) + add;
      if (tot > 30) throw ['A HND/BTS semester cannot exceed 30 credits (this would make ' + tot + ').'];
    }
  }
  if (c === 'apps' && n && n.status === 'admitted' && (!o || o.status !== 'admitted') && MB) {
    try { await MB.issueFromAdmission(u, n); } catch (e) { console.error('[mail] admission', e && e.message || e); }
  }
  if (c === 'msapp') { await sideMod('minesup-api.js').apply({ S, R, logic, save, audit, now, usersWith, notifyUser, bi }, u, id, o, n); return; }
  if (n === null) return remove(c, id);
  await save(c, id, n);
}

/* ---------- MoMo ---------- */
async function momoCheck(p) {
  const st = await momo.status(p.momoRef);
  const cur = S.get('payments', p.id); if (!cur || cur.status !== 'pending') return;
  if (st.status === 'SUCCESSFUL') { await confirmPayment(cur, 'MTN MoMo (automatic)', { ref: st.financialTransactionId || cur.ref }); await audit(null, 'momo payment confirmed ' + cur.id); }
  else if (st.status === 'FAILED' || now() - cur.at > 15 * 60e3) { const rc = String(st.reason || (st.status === 'FAILED' ? 'UNKNOWN' : 'EXPIRED')).toUpperCase().slice(0, 40); await save('payments', cur.id, Object.assign({}, cur, { status: 'rejected', reasonCode: rc, note: 'MoMo: ' + rc, rejectedAt: now() })); await notifyUser(cur.userId, bi('Payment not completed', 'Paiement non abouti'), cur.label + ' — ' + xaf(cur.amount) + ' (' + (st.reason || 'MoMo') + ')'); }
}
async function momoPoll() {
  if (!momo.enabled()) return;
  for (const p of Object.values(S.all('payments')).filter(x => x.status === 'pending' && x.momoRef)) { try { await momoCheck(p); } catch (e) { console.error('[momo] poll', p.id, e.message); } }
}

async function momoPay(u, b) {
  if (!momo.enabled()) throw [503, 'MoMo is not enabled on this server'];
  const st = R.myStudent(u); if (!st || !R.has(u, 'fees_pay')) throw [403, 'forbidden'];
  if (limited('momo:' + u.id, 6, 600e3)) throw [429, 'Too many attempts, try again later'];
  const price = logic.priceFor(S, st, b.kind); if (!price) throw [400, 'Unknown fee item'];
  const amount = price.custom ? Number(b.amount) : price.amount; if (!(amount > 0 && amount <= 5e6)) throw [400, 'Invalid amount'];
  const phone = momo.msisdn(b.phone); if (!/^237\d{9}$/.test(phone)) throw [400, 'Enter a Cameroon mobile number'];
  { // a request that is still waiting is resumed (never duplicated), so a student who closed the window can simply continue
    const pend = Object.values(S.all('payments')).find(p => p.userId === u.id && p.kind === b.kind && p.status === 'pending');
    if (pend) {
      if (pend.method === 'momo_api' && pend.momoRef) {
        try { await momoCheck(pend); } catch (e) { /* MTN not reachable right now: keep waiting */ }
        const cur = S.get('payments', pend.id);
        if (cur.status === 'pending') return { id: cur.id, ref: cur.ref, status: 'pending', resumed: true, phone: cur.payerPhone, amount: cur.amount };
        if (cur.status === 'confirmed') throw [409, bi('This payment was already confirmed', 'Ce paiement est déjà confirmé'), 'ALREADY_PAID'];
      } else throw [409, 'A payment for this item is already pending'];
    }
  }
  const id = uid('pay'); const label = price.custom ? String(b.desc || 'Other payment').slice(0, 200) : price.label;
  let ref;
  try { ref = await momo.requestToPay({ amount, phone, externalId: id, payerMessage: 'ADI ' + label.slice(0, 60), payeeNote: st.matric + ' ' + b.kind }); }
  catch (e) { const reason = momo.why(e); try { await S.setMeta('momoLast', { at: now(), reason, text: String(e.message).slice(0, 220) }); } catch (x) {} console.error('[momo] request failed:', e.message); throw [reason === 'PAYER_NOT_FOUND' ? 400 : 503, bi('The MoMo request could not be sent', "La demande MoMo n'a pas pu être envoyée"), reason]; }
  const p = { userId: u.id, matric: st.matric, payerName: st.name, kind: b.kind, label, amount, ref: 'MOMO-' + ref.slice(0, 8).toUpperCase(), momoRef: ref, payerPhone: '+' + phone, status: 'pending', at: now(), ay: logic.AY(), method: 'momo_api', currency: momo.currency() };
  await save('payments', id, p); await audit(u, 'momo request ' + id + ' ' + amount); setTimeout(momoPoll, 5000);
  return { id, ref, status: 'pending' };
}

/* ---------- AI assistant ---------- */
async function ai(u, b) {
  if (!E.ANTHROPIC_API_KEY) throw [503, 'AI assistant is not configured'];
  if (limited('ai:' + (u ? u.id : 'anon'), 30, 3600e3)) throw [429, 'Too many questions this hour'];
  const msgs = (Array.isArray(b.messages) ? b.messages : []).slice(-12).map(m => ({ role: m.role === 'assistant' ? 'assistant' : 'user', content: String(m.content || '').slice(0, 12000) }));
  const r = await fetch('https://api.anthropic.com/v1/messages', { method: 'POST', headers: { 'x-api-key': E.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' }, body: JSON.stringify({ model: E.AI_MODEL || 'claude-sonnet-5-5', max_tokens: 900, messages: msgs }) });
  if (!r.ok) throw [502, 'AI service error ' + r.status];
  const j = await r.json(); return { text: (j.content || []).filter(x => x.type === 'text').map(x => x.text).join('') };
}

/* ---------- static ---------- */
const INDEX = path.join(__dirname, 'public', 'index.html');
const SIGS_JSON = typeof __EMBED_SIGS !== 'undefined' ? __EMBED_SIGS : fs.readFileSync(path.join(__dirname, 'lib', 'signatures.json'), 'utf8');
const SEC = { 'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'same-origin', 'X-Frame-Options': 'SAMEORIGIN', 'Permissions-Policy': 'camera=(), microphone=(), geolocation=(self), publickey-credentials-get=(self), publickey-credentials-create=(self)',
  'Content-Security-Policy': "default-src 'self'; script-src 'self' 'unsafe-inline' https://cdnjs.cloudflare.com; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com https://cdn.jsdelivr.net; font-src https://fonts.gstatic.com https://cdn.jsdelivr.net; img-src 'self' data: blob:; media-src 'self'; frame-src https://www.youtube-nocookie.com https://player.vimeo.com https://drive.google.com; connect-src 'self'; frame-ancestors 'self'" };
if (PROD) SEC['Strict-Transport-Security'] = 'max-age=31536000';
// If the super administrator configures the school's own Jitsi server, the portal may show its video room in a frame and use the camera there — that one address only.
function secNow() {
  const d = logic.core.clsCfg((S && S.get('settings', 'main') || {}).cls).jitsiDomain;
  let headers = d ? Object.assign({}, SEC, { 'Permissions-Policy': SEC['Permissions-Policy'].replace('camera=()', `camera=(self "https://${d}")`).replace('microphone=()', `microphone=(self "https://${d}")`) + `, display-capture=(self "https://${d}")`, 'Content-Security-Policy': SEC['Content-Security-Policy'].replace('frame-src ', `frame-src https://${d} `) }) : SEC;
  if (!PROD) {
    headers = Object.assign({}, headers);
    delete headers['X-Frame-Options'];
    headers['Content-Security-Policy'] = String(headers['Content-Security-Policy']).replace("frame-ancestors 'self'", 'frame-ancestors *');
  }
  return headers;
}

// The PowerPoint library (PptxGenJS 4.0.1, MIT licence) is served by the portal itself, only when a lecturer exports a presentation.
